                if ic + 18 > lim {
                    flush!();
                    return deopt(c, fr, fr.pc(0x308), ic);
                }
                let ic0 = ic;
                ic += T[2] as u64;
                let taken = (at as u64) == (v0 as u64);
                a1 = w64(a1, ld64!(c, fr, fm, (at as u32).wrapping_add(0x10), 5, fr.pc(0x30c), ic0 + 2, 0));
                if taken {
                    let _ = go!(c, fr, 3);
                    break 'b2;
                }
                let _ = go!(c, fr, 4);
                // ---- block 3 @0x310 (0x2443d8): nop x4; beqz $a1,b2 (slot: addi $at,$at,0x20)
                ic += T[3] as u64;
                let zero_a1 = (a1 as u64) == 0;
                at = w32(at, (at as u32).wrapping_add(0x20));
                if zero_a1 {
                    let _ = go!(c, fr, 5);
                    continue 'b2;
                }
                let _ = go!(c, fr, 6);
