                //      vmulq.w vf2,vf0,vf0; sqc2 vf2,0($v1); addi $a0,$a0,1; j b2 (slot: addi $v1,$v1,0x20)
                let ic0 = ic;
                ic += T[4] as u64;
                vf1 = V::from_u128(ldvf!(c, fr, fm, (at as u32).wrapping_sub(0x10), 1, fr.pc(0x328), ic0 + 1, 9));
                g.begin();
                vf2 = V::from_u128(ldvf!(c, fr, fm, (at as u32).wrapping_sub(0x20), 2, fr.pc(0x32c), ic0 + 2, 8));
                g.begin();
                q = vdiv(vf4.lane::<0>(), vf1.lane::<3>());
                let r1 = vf1.prep().mul(vf3.prep().bcx());
                stk!(15, r1);
                (lv, any1) = (r1, true);
                vf1 = r1;
                st128!(c, fr, fm, (v1 as u32).wrapping_add(0x10), vf1.to_u128(), fr.pc(0x338), ic0 + 5, 5);
                g.begin();
                let r2 = p0.mul(V::splat(q).prep());
                stk!(8, r2);
                (lv, any1) = (r2, true);
                vf2 = vf2.blend::<8>(r2);
                st128!(c, fr, fm, (v1 as u32), vf2.to_u128(), fr.pc(0x340), ic0 + 7, 3);
