    macro_rules! st16 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $v:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_st!($c, $fr, $fm, w16, $a, $v, $pc, $ic, $rem) }; }
    macro_rules! st32 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $v:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_st!($c, $fr, $fm, w32, $a, $v, $pc, $ic, $rem) }; }
    macro_rules! st64 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $v:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_st!($c, $fr, $fm, w64, $a, $v, $pc, $ic, $rem) }; }
    macro_rules! st128 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $v:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_st!($c, $fr, $fm, w128, $a, $v, $pc, $ic, $rem) }; }
