    pub mod region {
    // Region 25 of moby_draw_build (0x2440c8), 0x2454d0..0x2454e8, 6 insns, 1 block, edge e0 (j -> EXIT 0x244d70). SPEED STYLE, RELOCATABLE.
    // Every pc is fr.pc(OFF). The one store is ONE st64! line (gen.rs): Fm fast path for RAM/scratchpad, else the recompiled code's own slow path.
    // Loads and stores stay in retail program order. flush!() writes back every modified register (at, t8) and icount.
    use super::gen::*;
    use crate::cpu::Cpu;
    use crate::hs::{deopt, due_within, Frame};
    use crate::hs_fast::{lo, sx32, wlo, Fm};
    
    pub fn region(c: &mut Cpu, fr: &Frame) -> bool {
        if c.pc != fr.pc(0x1408) {
            return false;
        }
        run(c, fr)
    }
    
    #[inline(always)]
    fn run(c: &mut Cpu, fr: &Frame) -> bool {
        let ic0 = c.icount;
        let mut ic = ic0;
        let fm = Fm::new(c);
        // Entry values (low 64 bits) of the registers the block reads or writes.
        let mut at = lo(c, 1);
        let mut t8 = lo(c, 24);
        // Write back EVERY register the block modified (idempotent; used before every exit, deopt and inline MMIO access).
        macro_rules! flush {
            () => {{
                c.icount = ic;
                wlo(c, 1, at);
                wlo(c, 24, t8);
            }};
        }
        if due_within(c, 6) {
            flush!();
            return deopt(c, fr, fr.pc(0x1408), ic0);
        }
        // ---- block 0 @fr.pc(0x1408): 6 insns, j -> EXIT 0x244d70 (e0). Access k (1-based insn number) = pc fr.pc(0x1408) + 4*(k-1), IC = ic0 + k, REM = 6 - k.
        ic += T[0] as u64;
        st64!(c, fr, fm, (t8 as u32), 0u64, fr.pc(0x1408), ic0 + 1, 5); // sd $zero, ($t8)
        at = 0x1000_0000; // lui $at, 0x1000
        t8 = sx32((t8 as u32).wrapping_add(0x10)); // addi $t8, $t8, 0x10
        at |= 0xd000; // ori $at, $at, 0xd000
        // j 0x244d70 (delay slot nop runs before the transfer; nothing to do)
        let _ = go!(c, fr, 0);
        return true;
    }
    }
