pub static RELOC_HAND: RelocHand = RelocHand { name: "moby_draw_build", reloc, est: hs::EXACT, f: hand };

/// Region entry offsets from the function base: a deopt runs retail only up to the next one (S2f resume), then the driver goes on in Rust.
pub static RESUME_OFFS: [u32; 37] = [0x0, 0x88, 0x108, 0x2c8, 0x358, 0x3c0, 0x488, 0x578, 0x610, 0x698, 0x740, 0x7f8, 0x938, 0x970, 0xa48, 0xb00, 0xb08, 0xb18, 0xc48, 0xca8, 0xd00, 0xd10, 0xd20, 0xd28, 0xe08, 0xe50, 0xe80, 0xed0, 0xf60, 0x1040, 0x10b8, 0x10d0, 0x10f0, 0x1160, 0x1190, 0x1310, 0x1408];

/// The stitched function: each region runs as Rust, one after the other, until the call returns. Entered with c.pc == the copy's entry.
fn hand(c: &mut Cpu) -> bool {
    let base = c.pc;
    let zv = reloc().zvals(&c.mem, base);
    let fr = Frame::enter_rel(c, base, &zv);
    let prev = hs::resume_set_rel_len(&fr, &RESUME_OFFS, LEN);
    let r = drive(c, &fr);
    hs::resume_restore(prev);
    r
}

fn drive(c: &mut Cpu, fr: &Frame) -> bool {
    loop {
        if fr.done(c) || c.stop.is_some() {
            return true;
        }
        let off = c.pc.wrapping_sub(fr.base);
        if off >= LEN {
            return true; // left through a host unwind (vblank wait): same as compiled code
        }
        hs::settle(c); // S9: a stale interrupt mark (both lines low) would deopt the region at its first due check
        let ok = match off {
            0x0 => r0::region::region(c, fr),
            0x88 => r1::region::region(c, fr),
            0x108 => r2::region::region(c, fr),
            0x2c8 => r3::region::region(c, fr),
            0x358 => r4::region::region(c, fr),
            0x3c0 => r5::region::region(c, fr),
            0x488 => r6::region::region(c, fr),
            0x578 => r7::region::region(c, fr),
            0x610 => r8::region::region(c, fr),
            0x698 => r9::region::region(c, fr),
            0x740 => r10::region::region(c, fr),
            0x7f8 => r11::region::region(c, fr),
            0x938 => r12::region::region(c, fr),
            0x970 => r13::region::region(c, fr),
            0xa48 | 0xb00 | 0xb08 => r14::region::region(c, fr),
            0xb18 => r15::region::region(c, fr),
            0xc48 | 0xca8 | 0xd00 | 0xd10 => r16::region::region(c, fr),
            0xd20 | 0xd28 => r17::region::region(c, fr),
            0xe08 | 0xe50 | 0xe80 => r18::region::region(c, fr),
            0xed0 => r19::region::region(c, fr),
            0xf60 => r20::region::region(c, fr),
            0x1040 | 0x10b8 | 0x10d0 => r21::region::region(c, fr),
            0x10f0 | 0x1160 => r22::region::region(c, fr),
            0x1190 => r23::region::region(c, fr),
            0x1310 => r24::region::region(c, fr),
            0x1408 => r25::region::region(c, fr),
            _ => false,
        };
        if !ok {
            // retail from here up to the next region entry (or the end of the call / an unwind), then the loop goes on
            let pc = c.pc;
            deopt(c, fr, pc, c.icount);
        }
    }
}
